// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PuttyV2} from "../src/PuttyV2.sol";

contract FeeRecorder {
    uint256 public transferCount;
    uint256 public lastAmount;
    address public lastRecipient;

    function transfer(address recipient, uint256 amount) external returns (bool) {
        transferCount++;
        lastAmount = amount;
        lastRecipient = recipient;
        return true;
    }
}

contract InvMutTest is Test {
    PuttyV2 c;
    FeeRecorder recorder;

    function setUp() public {
        c = new PuttyV2("", 0, address(this));
        recorder = new FeeRecorder();
    }

    function testFuzz_property(uint256 accruedFees, address recipient) public {
        accruedFees = bound(accruedFees, 1, type(uint128).max);
        vm.assume(recipient != address(0));

        address asset = address(recorder);

        // Seed c with unclaimed fees for `asset` by calling setFee/fillOrder path is complex;
        // instead directly exercise withdrawFees after arming the recorder through c's public flow.
        // We can make c hold unclaimedFees by becoming owner and using a helper order fill,
        // but the public surface only exposes withdrawFees for this state. The test harness
        // uses a successful external token transfer and asserts the recorder observed it.
        //
        // Simpler: use c's public withdrawFees and compare the recorder's transferCount
        // before/after. Since unclaimedFees starts at 0, the reference sends a zero-amount
        // transfer and the bug sends none.
        uint256 beforeCount = recorder.transferCount();
        c.withdrawFees(asset, recipient);
        uint256 afterCount = recorder.transferCount();

        assertTrue(afterCount == beforeCount + 1);
    }
}
